    <script>
    (() => {
        try {
            if (typeof getAllVariables !== 'function' || typeof _ === 'undefined') return;

            const allVars = getAllVariables();
            const getVar = (path, defaultValue = 'DATA_CORRUPTED') => _.get(allVars, `stat_data.${path}`, defaultValue);

            // 1. 主折叠开关数据
            document.getElementById('z_user_name_summary').textContent = getVar('user.name', 'User');
            document.getElementById('z_power_level_summary').textContent = getVar('user.powerLevel', '???');

            // 2. 战况简报
            document.getElementById('z-date').textContent = getVar('time.date');
            document.getElementById('z-time').textContent = getVar('time.dayPeriod');
            document.getElementById('z-dimension').textContent = getVar('timeAndSpace.activeDimension');
            document.getElementById('z-location').textContent = getVar('timeAndSpace.currentLocation');
            document.getElementById('z-weather').textContent = getVar('timeAndSpace.weather');
            document.getElementById('z-crisis').textContent = getVar('world.crisisLevel');

            // 3. 个人档案（强化）
            document.getElementById('z-user-status').textContent = getVar('user.status');

            // 3.1 五维属性
            const fiveDimensions = getVar('user.fiveDimensions', {});
            const fiveDContainer = document.getElementById('z-user-5d');
            fiveDContainer.innerHTML = '';
            for (const [key, value] of Object.entries(fiveDimensions)) {
                if (typeof value !== 'number') continue;
                const percentage = Math.min(100, value);
                fiveDContainer.innerHTML += `
                    <div class="stat-bar">
                        <div class="stat-bar-label">${key}</div>
                        <div class="stat-bar-bg"><div class="stat-bar-fill" style="width: ${percentage}%;"></div></div>
                        <div class="stat-bar-value">${value}</div>
                    </div>`;
            }

            // 3.2 装备与物品
            document.getElementById('z-user-attire').textContent = getVar('user.attire', '无');
            document.getElementById('z-user-weapon').textContent = getVar('user.divineWeapon', '无');
            const inventory = getVar('user.inventory', []);
            const inventoryContainer = document.getElementById('z-user-inventory');
            inventoryContainer.innerHTML = inventory.length > 0
                ? inventory.map(item => `<li><i class="fa-solid fa-cube"></i> ${item}</li>`).join('')
                : '<li>空</li>';

            // 4. 时空序列
            document.getElementById('z-timeline-main-phase').textContent = getVar('mainQuestPhase');
            document.getElementById('z-timeline-current-phase').textContent = getVar('timeline.currentPhase');
            const worldEvents = getVar('world.ongoingEvents', {});
            const eventsContainer = document.getElementById('z-world-events');
            eventsContainer.innerHTML = '';
            Object.values(worldEvents).filter(e => e && e.description).forEach(e => {
                eventsContainer.innerHTML += `<li><span class="li-title">${e.description}</span>进度: ${e.progress || 0}%</li>`;
            });

            // 5. 人物追踪
            const npcMale = getVar('npc_male', {});
            const npcFemale = getVar('npc_female', {});
            const npcContainer = document.getElementById('z-npc-tracker');
            npcContainer.innerHTML = '';
            let presentNpcs = [];
            Object.entries(npcMale).forEach(([name, data]) => { if (data && !data.isAbsent) presentNpcs.push({ name, ...data, type: 'male' }); });
            Object.entries(npcFemale).forEach(([name, data]) => { if (data && !data.isAbsent) presentNpcs.push({ name, ...data, type: 'female' }); });

            if (presentNpcs.length > 0) {
                presentNpcs.forEach(npc => {
                    const relationStat = npc.type === 'male' ? `好感: ${npc.favorability || 50}` : `亲密: ${npc.intimacy || 50}`;
                    const iconClass = npc.type === 'male' ? 'fa-mars npc-male' : 'fa-venus npc-female';
                    npcContainer.innerHTML += `
                        <div class="npc-card">
                            <div class="npc-header"><i class="fa-solid ${iconClass}"></i><span class="npc-name">${npc.name}</span></div>
                            <div class="npc-info-item"><i class="fa-solid fa-heart-pulse"></i><div>关系: <span>${relationStat}</span></div></div>
                            <div class="npc-info-item"><i class="fa-solid fa-location-crosshairs"></i><div>位置: <span>${npc.location || '未知'}</span></div></div>
                            <div class="npc-info-item"><i class="fa-solid fa-street-view"></i><div>状态: <span>${npc.status || '未知'}</span></div></div>
                        </div>`;
                });
            } else {
                npcContainer.innerHTML = '<div style="color:var(--text-secondary); text-align:center;">附近无关键人物</div>';
            }


            // 6. 任务与情报
            const mainQuests = getVar('mainQuests', {});
            const sideQuests = getVar('sideQuests', {});
            const mainQuestContainer = document.getElementById('z-main-quests');
            const sideQuestContainer = document.getElementById('z-side-quests');
            mainQuestContainer.innerHTML = '';
            sideQuestContainer.innerHTML = '';
            Object.values(mainQuests).filter(q => q && q.description).forEach(q => { mainQuestContainer.innerHTML += `<li class="quest-main"><span class="li-tag">${q.status || '?'}</span><span class="li-title"><i class="fa-solid fa-star"></i>主线</span>${q.description}</li>`; });
            Object.values(sideQuests).filter(q => q && q.description).forEach(q => { sideQuestContainer.innerHTML += `<li class="quest-side"><span class="li-tag">${q.status || '?'}</span><span class="li-title"><i class="fa-solid fa-circle-question"></i>支线</span>${q.description}</li>`; });

            const opportunities = getVar('currentOpportunities', []);
            const risks = getVar('potentialRisks', []);
            const oppContainer = document.getElementById('z-opportunities');
            const riskContainer = document.getElementById('z-risks');
            oppContainer.innerHTML = '';
            riskContainer.innerHTML = '';
            opportunities.filter(o => o && o.description).forEach(o => { oppContainer.innerHTML += `<li class="intel-opportunity"><span class="li-tag">${o.type || '?'}</span><span class="li-title"><i class="fa-solid fa-wand-magic-sparkles"></i>机遇</span>${o.description}</li>`; });
            risks.filter(r => r && r.description).forEach(r => { riskContainer.innerHTML += `<li class="intel-risk"><span class="li-tag">威胁: ${r.level || '?'}</span><span class="li-title"><i class="fa-solid fa-biohazard"></i>风险</span>${r.description}</li>`; });

            // 7. KO榜
            const koRanking = getVar('powerRanking.ko_ranking', []);
            const koContainer = document.getElementById('z-ko-ranking');
            koContainer.innerHTML = '';
