        let usedPoints = 0;
        document.querySelectorAll('.attr-slider').forEach(slider => {
            usedPoints += parseInt(slider.value, 10);
        });
        const remainingPoints = totalPoints - usedPoints;
        document.getElementById('points-remaining').textContent = remainingPoints;

        document.querySelectorAll('.attr-slider').forEach(slider => {
            const currentValue = parseInt(slider.value, 10);
            const sliderMax = Math.min(maxAttrValue, currentValue + remainingPoints);
            slider.max = sliderMax < currentValue ? currentValue : sliderMax;
        });
        drawRadarChart();
    }

    function drawRadarChart() {
        const chartSize = 50;
        const polygon = document.getElementById('radar-data-shape');
        const points = [];
        const attrOrder = ['力量', '敏捷', '智力', '耐力', '魅力'];
        const angles = [ -Math.PI / 2, (-Math.PI / 2) + (2 * Math.PI / 5), (-Math.PI / 2) + (4 * Math.PI / 5), (-Math.PI / 2) + (6 * Math.PI / 5), (-Math.PI / 2) + (8 * Math.PI / 5) ];

        attrOrder.forEach((name, i) => {
            const slider = document.querySelector(`.attr-slider[name="${name}"]`);
            const value = parseInt(slider.value, 10) / maxAttrValue;
            const angle = angles[i];
            const x = chartSize + chartSize * value * Math.cos(angle);
            const y = chartSize + chartSize * value * Math.sin(angle);
            points.push(`${x},${y}`);
        });

        polygon.setAttribute('points', points.join(' '));
