            if(index < arr.length - 1){
                slider.value = initialValue;
                distributedPoints += initialValue;
            } else {
                slider.value = Math.max(1, points - distributedPoints);
            }
            slider.dispatchEvent(new Event('input'));
        });
        updatePoints();
    }

