- 【核心修正】将 user.background 更新为: '${background}'
- 将 user.fiveDimensions 更新为: ${JSON.stringify(attributes)}
- 将 user.status 更新为: '作为新转学生，刚刚踏入终极一班教室，正在适应新环境。'
`
        const command = `/echo severity=success 档案已生成，正在接入终极序列... | /send ${instructionForAI.replace(/\n/g, ' ')} | /trigger`;

        if (typeof triggerSlash === 'function') {
            triggerSlash(command);
        } else {
            console.warn("triggerSlash function not available.");
            alert("请在SillyTavern环境下使用此功能。");
            console.log("Generated command:", command);
        }
    }
    // ==================【小游戏逻辑】==================
    let secretNumber;
    let attempts;
    const maxAttempts = 7;

    function startGuessGame() {
        secretNumber = Math.floor(Math.random() * 100) + 1;
        attempts = 0;
        document.getElementById('game-message').textContent = '';
        document.getElementById('guess-input').value = '';
        document.getElementById('guess-input').disabled = false;
        document.getElementById('guess-button').disabled = false;
    }

    function checkGuess() {
        const guessInput = document.getElementById('guess-input');
        const gameMessage = document.getElementById('game-message');
        const guessButton = document.getElementById('guess-button');
        const userGuess = parseInt(guessInput.value, 10);

        if (isNaN(userGuess) || userGuess < 1 || userGuess > 100) {
            gameMessage.textContent = "无效输入，请输入1到100之间的数字。";
            gameMessage.style.color = 'var(--color-accent)';
            return;
        }

        attempts++;

        if (userGuess === secretNumber) {
            gameMessage.textContent = `密码正确！【${secretNumber}】你只用了 ${attempts} 次就破译了序列！`;
            gameMessage.style.color = 'var(--color-secondary)';
            guessInput.disabled = true;
            guessButton.disabled = true;
        } else if (attempts >= maxAttempts) {
            gameMessage.textContent = `机会用尽！正确密码是【${secretNumber}】。序列接入失败...重启中。`;
            gameMessage.style.color = 'var(--color-primary)';
            guessInput.disabled = true;
            guessButton.disabled = true;
            setTimeout(startGuessGame, 3000);
        } else if (userGuess < secretNumber) {
            gameMessage.textContent = `序列信号过弱... [尝试次数: ${attempts}/${maxAttempts}]`;
            gameMessage.style.color = 'var(--text-light)';
        } else {
            gameMessage.textContent = `序列信号过强... [尝试次数: ${attempts}/${maxAttempts}]`;
            gameMessage.style.color = 'var(--text-light)';
        }
         guessInput.value = '';
    }
    // =================================================================

    // --- 事件监听 ---
    document.addEventListener('DOMContentLoaded', () => {
         document.querySelectorAll('input[name="difficulty"]').forEach(radio => {
            radio.addEventListener('change', (event) => {
                const passwordField = document.getElementById('password-field');
                if (event.target.value === 'cheat') {
                    passwordField.classList.add('visible');
                    handleCheatMode();
                } else {
                    passwordField.classList.remove('visible');
                    setDifficulty(parseInt(event.target.value, 10));
                }
            });
        });

        document.getElementById('password-input').addEventListener('input', handleCheatMode);

        document.querySelectorAll('.attr-slider').forEach(slider => {
            const valueSpan = slider.nextElementSibling;
            slider.addEventListener('input', () => {
                valueSpan.textContent = slider.value;
                updatePoints();
            });
        });

        document.getElementById('guess-button').addEventListener('click', checkGuess);
        document.getElementById('guess-input').addEventListener('keypress', function(event) {
            if (event.key === 'Enter') {
                event.preventDefault();
                checkGuess();
            }
        });

        setDifficulty(100);
        startGuessGame();
    });
</script>
