                <p>在十二个时空构成的宇宙中，金时空是相对和平的一个。但和平之下，暗流涌动。KO榜高手如云，神秘的武力裁决所潜藏在暗处，时空秩序的守护者——时空盟，似乎也对这里的异动有所察察。你，一个身份成谜的转学生，刚刚踏入芭乐高中的大门，来到了风暴的中心——终极一班。你的到来，是偶然，还是宿命？</p>
            </div>
        </section>

    </div>

<script>
    let totalPoints = 100;
    let attributes = { '力量': 1, '敏捷': 1, '智力': 1, '耐力': 1, '魅力': 1 };
    const maxAttrValue = 100;

    function updatePoints() {
        let usedPoints = 0;
        document.querySelectorAll('.attr-slider').forEach(slider => {
            usedPoints += parseInt(slider.value, 10);
        });
        const remainingPoints = totalPoints - usedPoints;
        document.getElementById('points-remaining').textContent = remainingPoints;

        document.querySelectorAll('.attr-slider').forEach(slider => {
            const currentValue = parseInt(slider.value, 10);
            const sliderMax = Math.min(maxAttrValue, currentValue + remainingPoints);
            slider.max = sliderMax < currentValue ? currentValue : sliderMax;
        });
        drawRadarChart();
    }

    function drawRadarChart() {
        const chartSize = 50;
        const polygon = document.getElementById('radar-data-shape');
        const points = [];
        const attrOrder = ['力量', '敏捷', '智力', '耐力', '魅力'];
        const angles = [ -Math.PI / 2, (-Math.PI / 2) + (2 * Math.PI / 5), (-Math.PI / 2) + (4 * Math.PI / 5), (-Math.PI / 2) + (6 * Math.PI / 5), (-Math.PI / 2) + (8 * Math.PI / 5) ];

        attrOrder.forEach((name, i) => {
            const slider = document.querySelector(`.attr-slider[name="${name}"]`);
            const value = parseInt(slider.value, 10) / maxAttrValue;
            const angle = angles[i];
            const x = chartSize + chartSize * value * Math.cos(angle);
            const y = chartSize + chartSize * value * Math.sin(angle);
            points.push(`${x},${y}`);
        });

        polygon.setAttribute('points', points.join(' '));
    }

    function setDifficulty(points) {
        totalPoints = points;
        let initialValue = Math.floor(points / 5);
        if(points < 5) initialValue = 1;

        let distributedPoints = 0;
        document.querySelectorAll('.attr-slider').forEach((slider, index, arr) => {
            if(index < arr.length - 1){
                slider.value = initialValue;
                distributedPoints += initialValue;
            } else {
                slider.value = Math.max(1, points - distributedPoints);
            }
            slider.dispatchEvent(new Event('input'));
        });
        updatePoints();
    }

    function handleCheatMode() {
        const passwordInput = document.getElementById('password-input');
        if (passwordInput.value === '禁止商用') {
            totalPoints = 5 * maxAttrValue;
            document.querySelectorAll('.attr-slider').forEach(slider => {
                slider.value = maxAttrValue;
                slider.dispatchEvent(new Event('input'));
            });
            passwordInput.style.borderColor = 'var(--color-secondary)';
        } else {
            passwordInput.style.borderColor = 'var(--color-primary)';
        }
        updatePoints();
    }

    // ==================【角色创建提交逻辑】==================
    async function submitProfileForm() {
        const name = document.getElementById('user-name').value;
        const gender = document.getElementById('user-gender').value;
        const age = document.getElementById('user-age').value;
        // 【核心修正】获取出身背景信息
        const background = document.getElementById('user-background').value;

         document.querySelectorAll('.attr-slider').forEach(slider => {
            attributes[slider.name] = parseInt(slider.value, 10);
        });
        const powerLevel = totalPoints * 10;

        const instructionForAI = `
一名叫“${name}”的新转学生进入了终极一班，请开始叙事。
同时，根据以下初始信息，在你本次回应的末尾，严格按照格式生成用于更新变量的 <UpdateVariable> 代码块：
- 将 user.name 更新为: '${name}'
- 将 user.powerLevel 更新为: ${powerLevel}
- 【核心修正】将 user.background 更新为: '${background}'
- 将 user.fiveDimensions 更新为: ${JSON.stringify(attributes)}
- 将 user.status 更新为: '作为新转学生，刚刚踏入终极一班教室，正在适应新环境。'
`
        const command = `/echo severity=success 档案已生成，正在接入终极序列... | /send ${instructionForAI.replace(/\n/g, ' ')} | /trigger`;

        if (typeof triggerSlash === 'function') {
            triggerSlash(command);
        } else {
            console.warn("triggerSlash function not available.");
            alert("请在SillyTavern环境下使用此功能。");
            console.log("Generated command:", command);
        }
    }
    // ==================【小游戏逻辑】==================
    let secretNumber;
    let attempts;
    const maxAttempts = 7;

    function startGuessGame() {
        secretNumber = Math.floor(Math.random() * 100) + 1;
        attempts = 0;
        document.getElementById('game-message').textContent = '';
        document.getElementById('guess-input').value = '';
        document.getElementById('guess-input').disabled = false;
        document.getElementById('guess-button').disabled = false;
    }

    function checkGuess() {
        const guessInput = document.getElementById('guess-input');
        const gameMessage = document.getElementById('game-message');
        const guessButton = document.getElementById('guess-button');
        const userGuess = parseInt(guessInput.value, 10);

        if (isNaN(userGuess) || userGuess < 1 || userGuess > 100) {
            gameMessage.textContent = "无效输入，请输入1到100之间的数字。";
            gameMessage.style.color = 'var(--color-accent)';
            return;
        }

        attempts++;

        if (userGuess === secretNumber) {
            gameMessage.textContent = `密码正确！【${secretNumber}】你只用了 ${attempts} 次就破译了序列！`;
            gameMessage.style.color = 'var(--color-secondary)';
            guessInput.disabled = true;
            guessButton.disabled = true;
        } else if (attempts >= maxAttempts) {
            gameMessage.textContent = `机会用尽！正确密码是【${secretNumber}】。序列接入失败...重启中。`;
            gameMessage.style.color = 'var(--color-primary)';
            guessInput.disabled = true;
            guessButton.disabled = true;
            setTimeout(startGuessGame, 3000);
        } else if (userGuess < secretNumber) {
            gameMessage.textContent = `序列信号过弱... [尝试次数: ${attempts}/${maxAttempts}]`;
            gameMessage.style.color = 'var(--text-light)';
        } else {
            gameMessage.textContent = `序列信号过强... [尝试次数: ${attempts}/${maxAttempts}]`;
            gameMessage.style.color = 'var(--text-light)';
        }
         guessInput.value = '';
    }
    // =================================================================

    // --- 事件监听 ---
    document.addEventListener('DOMContentLoaded', () => {
         document.querySelectorAll('input[name="difficulty"]').forEach(radio => {
            radio.addEventListener('change', (event) => {
                const passwordField = document.getElementById('password-field');
                if (event.target.value === 'cheat') {
                    passwordField.classList.add('visible');
                    handleCheatMode();
                } else {
                    passwordField.classList.remove('visible');
                    setDifficulty(parseInt(event.target.value, 10));
                }
            });
        });

        document.getElementById('password-input').addEventListener('input', handleCheatMode);

        document.querySelectorAll('.attr-slider').forEach(slider => {
            const valueSpan = slider.nextElementSibling;
            slider.addEventListener('input', () => {
                valueSpan.textContent = slider.value;
                updatePoints();
            });
        });

        document.getElementById('guess-button').addEventListener('click', checkGuess);
        document.getElementById('guess-input').addEventListener('keypress', function(event) {
            if (event.key === 'Enter') {
                event.preventDefault();
                checkGuess();
            }
        });

        setDifficulty(100);
        startGuessGame();
    });
</script>
</body>
</html>
